{"results": [{"id": "hp_doc_658cc789aabcbf1d2ac2f3029b1909c575acd328038cdec28196ff6304da1229", "title": "From Dusk Till Dawn (soundtrack)", "text": "From Dusk Till Dawn: Music from the Motion Picture is the soundtrack album for the 1996 action-comedy-horror film, \"From Dusk till Dawn\", directed by Robert Rodriguez and screenplay by Quentin Tarantino.", "score": 32.2179}, {"id": "hp_doc_ed54f2b8092842374846495bdf3fc9dae4e0fcd265d0ba31bb1bb028ae9a3ac6", "title": "From Dusk Till Dawn (video game)", "text": "From Dusk Till Dawn is a 2001 third-person shooter video game that is based on events that transpire directly after the end of \"From Dusk till Dawn\". Released for Windows, it was distributed by Cryo Interactive.", "score": 31.7221}, {"id": "hp_doc_04c83dc1f60830db19160ad389bd01da569453aa41c880c3d21001a67861eb70", "title": "Dusk Till Dawn (Zayn song)", "text": "\"Dusk Till Dawn\" is a song by English singer Zayn featuring Australian singer-songwriter Sia, which was released worldwide as the lead single from his upcoming second studio album on 7 September 2017. The accompanying music video was released the same day, it features Zayn and American actress Jemima Kirke. The song is also featured in the official trailer for the film, \"The Mountain Between Us\".", "score": 30.1308}], "remaining_searches": 2}
